begin;
insert into clinic_finance.accounts values('2120','مستحقات الأطباء','liability'),('5111','أتعاب ونسب الأطباء','expense'),('2141','ضرائب مستقطعة مستحقة','liability') on conflict do nothing;
create table if not exists clinic_finance.doctor_contracts(id uuid primary key default gen_random_uuid(),doctor_key text not null,doctor_name text not null,service_scope text not null,valid_from date not null,valid_to date not null,rate numeric(8,4) not null check(rate between 0 and 100),basis text not null check(basis in ('performed','collected')),base_scope text not null check(base_scope in ('service','invoice')),deduction text not null check(deduction in ('none','cost','sale')),refund_policy text not null check(refund_policy='proportional_revenue'),reference text not null,status text not null default 'pending' check(status in ('pending','active','rejected')),payload jsonb not null,created_by uuid not null references public.admins(id),token uuid not null,created_at timestamptz not null default now(),reviewed_by uuid references public.admins(id),reviewed_at timestamptz,review_note text,unique(created_by,token),check(valid_from<=valid_to));
create table if not exists clinic_finance.doctor_allocations(invoice_id uuid primary key references clinic_finance.invoices(id),contract_id uuid not null references clinic_finance.doctor_contracts(id),doctor_key text not null,doctor_name text not null,terms jsonb not null,original_base numeric(14,2) not null,original_deduction numeric(14,2) not null,earned numeric(14,2) not null default 0,created_at timestamptz not null default now());
create table if not exists clinic_finance.doctor_accruals(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references clinic_finance.doctor_allocations(invoice_id),doctor_key text not null,delta numeric(14,2) not null check(delta<>0),created_at timestamptz not null default now());
create table if not exists clinic_finance.doctor_payouts(id uuid primary key default gen_random_uuid(),doctor_key text not null,gross numeric(14,2) not null check(gross>0),withheld numeric(14,2) not null check(withheld>=0 and withheld<=gross),method text not null check(method in ('cash','bank')),shift_id uuid references clinic_finance.shifts(id),reference text not null,period_from date not null,period_to date not null,payload jsonb not null,created_by uuid not null references public.admins(id),token uuid not null,created_at timestamptz not null default now(),status text not null default 'pending' check(status in ('pending','approved','rejected')),reviewed_by uuid references public.admins(id),reviewed_at timestamptz,review_note text,unique(created_by,token),check(period_from<=period_to));
create unique index if not exists doctor_paid_reference on clinic_finance.doctor_payouts(method,reference) where status='approved';
create index if not exists doctor_accrual_key on clinic_finance.doctor_accruals(doctor_key);
create index if not exists doctor_payout_key on clinic_finance.doctor_payouts(doctor_key,status);
do $$ declare t text;begin foreach t in array array['doctor_contracts','doctor_allocations','doctor_accruals','doctor_payouts'] loop execute format('alter table clinic_finance.%I enable row level security',t);execute format('revoke all on clinic_finance.%I from public,anon,authenticated',t);end loop;end $$;
create or replace function clinic_finance.doctor_balance(p_key text) returns numeric language sql stable security definer set search_path=pg_catalog,public as $$select coalesce((select sum(delta) from clinic_finance.doctor_accruals where doctor_key=p_key),0)-coalesce((select sum(gross) from clinic_finance.doctor_payouts where doctor_key=p_key and status='approved'),0);$$;
create or replace function clinic_finance.doctor_sync(p_invoice uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$
declare a clinic_finance.doctor_allocations%rowtype;i clinic_finance.invoices%rowtype;refund numeric;adjustment numeric;revenue numeric;collected numeric;target numeric;delta numeric;event_id uuid;
begin
 select * into a from clinic_finance.doctor_allocations where invoice_id=p_invoice for update;if not found then return;end if;select * into i from clinic_finance.invoices where id=p_invoice;
 select coalesce(sum(amount),0) into refund from clinic_finance.requests where invoice_id=i.id and kind='refund' and status='approved';
 select coalesce(sum(x.amount),0) into adjustment from clinic_finance.insurance_actions x join clinic_finance.insurance_claims c on c.id=x.claim_id where c.invoice_id=i.id and x.kind='contractual' and x.status='approved';
 revenue:=case when i.voided then 0 else greatest(0,i.amount-refund-adjustment) end;
 collected:=greatest(0,coalesce((select sum(amount) from clinic_finance.payments where invoice_id=i.id),0)-refund+coalesce((select sum(x.amount) from clinic_finance.insurance_actions x join clinic_finance.insurance_claims c on c.id=x.claim_id where c.invoice_id=i.id and x.kind='payment' and x.status='approved'),0));
 target:=greatest(0,a.original_base*revenue/i.amount-a.original_deduction)*(a.terms->>'rate')::numeric/100;
 if a.terms->>'basis'='collected' then target:=case when revenue>0 then target*least(1,collected/revenue) else 0 end;end if;
 target:=round(target,2);delta:=target-a.earned;
 if delta<>0 then insert into clinic_finance.doctor_accruals(invoice_id,doctor_key,delta) values(i.id,a.doctor_key,delta) returning id into event_id;
 perform clinic_finance.post('doctor_accrual',event_id,'استحقاق أو تسوية أتعاب '||a.doctor_name||' — '||i.reference,null,case when delta>0 then '5111' else '2120' end,case when delta>0 then '2120' else '5111' end,abs(delta));update clinic_finance.doctor_allocations set earned=target where invoice_id=i.id;end if;
end $$;
create or replace function public.clinic_finance_doctor_command(p_action text,p_payload jsonb,p_token uuid) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$
declare me uuid;v_id uuid;c clinic_finance.doctor_contracts%rowtype;r clinic_finance.doctor_payouts%rowtype;amount numeric;tax numeric;approval boolean;
begin perform clinic_finance.lock_day();
 if p_action='contract' then me:=clinic_finance.require_access('create');select * into c from clinic_finance.doctor_contracts where created_by=me and token=p_token;if found then if c.payload is distinct from p_payload then raise exception 'مفتاح طلب مختلف';end if;return c.id;end if;
 if length(trim(coalesce(p_payload->>'doctor_key','')))<2 or length(trim(coalesce(p_payload->>'doctor_name','')))<2 or length(trim(coalesce(p_payload->>'scope','')))<2 or length(trim(coalesce(p_payload->>'reference','')))<2 or (p_payload->>'rate')::numeric::text in ('NaN','Infinity','-Infinity') then raise exception 'راجع بيانات الطبيب والعقد والنسبة';end if;
 insert into clinic_finance.doctor_contracts(doctor_key,doctor_name,service_scope,valid_from,valid_to,rate,basis,base_scope,deduction,refund_policy,reference,payload,created_by,token) values(trim(p_payload->>'doctor_key'),trim(p_payload->>'doctor_name'),trim(p_payload->>'scope'),(p_payload->>'from')::date,(p_payload->>'to')::date,(p_payload->>'rate')::numeric,p_payload->>'basis',p_payload->>'base_scope',p_payload->>'deduction',p_payload->>'refund_policy',trim(p_payload->>'reference'),p_payload,me,p_token) returning id into v_id;
 elsif p_action='contract_review' then me:=clinic_finance.require_access('review');select * into c from clinic_finance.doctor_contracts where id=(p_payload->>'id')::uuid for update;approval:=(p_payload->>'approve')::boolean;
 if not found or c.created_by=me or c.status<>'pending' or approval is null or length(trim(coalesce(p_payload->>'note','')))<3 then raise exception 'العقد غير متاح أو لا يمكنك اعتماد عقدك';end if;
 if approval and exists(select 1 from clinic_finance.doctor_contracts where doctor_key=c.doctor_key and service_scope=c.service_scope and status='active' and valid_from<=c.valid_to and valid_to>=c.valid_from) then raise exception 'فترة العقد تتداخل مع عقد معتمد لنفس الطبيب والخدمة';end if;
 update clinic_finance.doctor_contracts set status=case when approval then 'active' else 'rejected' end,reviewed_by=me,reviewed_at=now(),review_note=p_payload->>'note' where id=c.id;v_id:=c.id;
 elsif p_action='payout' then me:=clinic_finance.require_access('create');select * into r from clinic_finance.doctor_payouts where created_by=me and token=p_token;if found then if r.payload is distinct from p_payload then raise exception 'مفتاح طلب مختلف';end if;return r.id;end if;
 amount:=(p_payload->>'gross')::numeric;tax:=(p_payload->>'withheld')::numeric;
 if amount is null or amount<=0 or amount::text in ('NaN','Infinity','-Infinity') or amount<>round(amount,2) or tax is null or tax<0 or tax>amount or tax<>round(tax,2) or length(trim(coalesce(p_payload->>'reference','')))<2 then raise exception 'راجع مبالغ التسوية ومرجع السداد';end if;
 if amount+coalesce((select sum(gross) from clinic_finance.doctor_payouts where doctor_key=p_payload->>'doctor_key' and status='pending'),0)>clinic_finance.doctor_balance(p_payload->>'doctor_key') then raise exception 'المبلغ يتجاوز رصيد الطبيب المتاح';end if;
 if p_payload->>'method'='cash' then perform clinic_finance.check_shift((p_payload->>'shift_id')::uuid);end if;
 insert into clinic_finance.doctor_payouts(doctor_key,gross,withheld,method,shift_id,reference,period_from,period_to,payload,created_by,token) values(p_payload->>'doctor_key',amount,tax,p_payload->>'method',case when p_payload->>'method'='cash' then (p_payload->>'shift_id')::uuid end,trim(p_payload->>'reference'),(p_payload->>'from')::date,(p_payload->>'to')::date,p_payload,me,p_token) returning id into v_id;
 elsif p_action='payout_review' then me:=clinic_finance.require_access('review');select * into r from clinic_finance.doctor_payouts where id=(p_payload->>'id')::uuid for update;approval:=(p_payload->>'approve')::boolean;
 if not found or r.created_by=me or r.status<>'pending' or approval is null or length(trim(coalesce(p_payload->>'note','')))<3 then raise exception 'التسوية غير متاحة أو لا يمكنك اعتماد طلبك';end if;
 if approval then if r.gross>clinic_finance.doctor_balance(r.doctor_key) then raise exception 'رصيد الطبيب تغير؛ أعد مراجعة التسوية';end if;
 if r.gross>r.withheld then perform clinic_finance.post('doctor_payment',r.id,'صرف مستحقات طبيب — '||r.reference,r.shift_id,'2120',case when r.method='cash' then '1111' else '1112' end,r.gross-r.withheld);end if;
 if r.withheld>0 then perform clinic_finance.post('doctor_withholding',r.id,'ضريبة مستقطعة موثقة — '||r.reference,null,'2120','2141',r.withheld);end if;end if;
 update clinic_finance.doctor_payouts set status=case when approval then 'approved' else 'rejected' end,reviewed_by=me,reviewed_at=now(),review_note=p_payload->>'note' where id=r.id;v_id:=r.id;
 else raise exception 'إجراء غير معروف';end if;
 insert into clinic_finance.audit(actor,action,entity_id,detail) values(me,'doctor_'||p_action,v_id,jsonb_build_object('note',p_payload->>'note'));return v_id;
end $$;
do $$begin
 if to_regprocedure('clinic_finance.doctor_bill_base(jsonb,uuid)') is null then alter function public.clinic_finance_bill(jsonb,uuid) set schema clinic_finance;alter function clinic_finance.clinic_finance_bill(jsonb,uuid) rename to doctor_bill_base;end if;
 if to_regprocedure('clinic_finance.doctor_collect_base(uuid,uuid,text,numeric,text,uuid)') is null then alter function public.clinic_finance_collect(uuid,uuid,text,numeric,text,uuid) set schema clinic_finance;alter function clinic_finance.clinic_finance_collect(uuid,uuid,text,numeric,text,uuid) rename to doctor_collect_base;end if;
 if to_regprocedure('clinic_finance.doctor_request_review_base(uuid,boolean,text)') is null then alter function public.clinic_finance_review_request(uuid,boolean,text) set schema clinic_finance;alter function clinic_finance.clinic_finance_review_request(uuid,boolean,text) rename to doctor_request_review_base;end if;
 if to_regprocedure('clinic_finance.doctor_insurance_review_base(uuid,boolean,text)') is null then alter function public.clinic_finance_insurance_review(uuid,boolean,text) set schema clinic_finance;alter function clinic_finance.clinic_finance_insurance_review(uuid,boolean,text) rename to doctor_insurance_review_base;end if;
 if to_regprocedure('clinic_finance.doctor_snapshot_base(date,date,integer)') is null then alter function public.clinic_finance_snapshot(date,date,integer) set schema clinic_finance;alter function clinic_finance.clinic_finance_snapshot(date,date,integer) rename to doctor_snapshot_base;end if;
end $$;
create or replace function public.clinic_finance_bill(p_payload jsonb,p_token uuid) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$
declare v_id uuid;c clinic_finance.doctor_contracts%rowtype;i clinic_finance.invoices%rowtype;sales numeric;cost numeric;ded numeric;
begin v_id:=clinic_finance.doctor_bill_base(p_payload,p_token);
 if nullif(p_payload->>'doctor_contract_id','') is not null and not exists(select 1 from clinic_finance.doctor_allocations where invoice_id=v_id) then
 select * into c from clinic_finance.doctor_contracts where id=(p_payload->>'doctor_contract_id')::uuid and status='active' and (now() at time zone 'Africa/Cairo')::date between valid_from and valid_to;if not found then raise exception 'عقد الطبيب غير معتمد أو خارج فترة سريانه';end if;
 select * into i from clinic_finance.invoices where id=v_id;select coalesce(sum(round(quantity*sale_price,2)),0),coalesce(sum(cost_total),0) into sales,cost from clinic_finance.bill_items where invoice_id=v_id;
 ded:=case c.deduction when 'cost' then cost when 'sale' then sales else 0 end;
 insert into clinic_finance.doctor_allocations(invoice_id,contract_id,doctor_key,doctor_name,terms,original_base,original_deduction) values(i.id,c.id,c.doctor_key,c.doctor_name,to_jsonb(c),case when c.base_scope='service' then i.amount-sales else i.amount end,ded);
 perform clinic_finance.doctor_sync(i.id);end if;return v_id;end $$;
create or replace function public.clinic_finance_collect(p_invoice uuid,p_shift uuid,p_method text,p_amount numeric,p_reference text,p_token uuid) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$declare v uuid;begin v:=clinic_finance.doctor_collect_base(p_invoice,p_shift,p_method,p_amount,p_reference,p_token);perform clinic_finance.doctor_sync(p_invoice);return v;end $$;
create or replace function public.clinic_finance_review_request(p_id uuid,p_approve boolean,p_note text) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$declare v uuid;i uuid;begin v:=clinic_finance.doctor_request_review_base(p_id,p_approve,p_note);select invoice_id into i from clinic_finance.requests where id=v;perform clinic_finance.doctor_sync(i);return v;end $$;
create or replace function public.clinic_finance_insurance_review(p_id uuid,p_approve boolean,p_note text) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$declare v uuid;i uuid;begin v:=clinic_finance.doctor_insurance_review_base(p_id,p_approve,p_note);select c.invoice_id into i from clinic_finance.insurance_actions a join clinic_finance.insurance_claims c on c.id=a.claim_id where a.id=v;perform clinic_finance.doctor_sync(i);return v;end $$;
create or replace function public.clinic_finance_snapshot(p_from date,p_to date,p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$
declare v jsonb:=clinic_finance.doctor_snapshot_base(p_from,p_to,p_offset);me uuid:=public.my_admin_id();reviewer boolean:=clinic_finance.allowed('review');
begin return v||jsonb_build_object('doctor_contracts',(select coalesce(jsonb_agg(x),'[]') from(select to_jsonb(c) x from clinic_finance.doctor_contracts c where reviewer or c.created_by=me or c.status='active' order by c.created_at desc,c.id desc limit 500)t),
 'doctor_balances',case when reviewer then(select coalesce(jsonb_agg(x),'[]') from(select doctor_key,max(doctor_name) doctor_name,clinic_finance.doctor_balance(doctor_key) balance from clinic_finance.doctor_contracts where status='active' group by doctor_key)x) else '[]'::jsonb end,
 'doctor_allocations',(select coalesce(jsonb_agg(x),'[]') from(select to_jsonb(a)||jsonb_build_object('invoice_reference',i.reference) x from clinic_finance.doctor_allocations a join clinic_finance.invoices i on i.id=a.invoice_id where (reviewer or i.created_by=me) and (a.created_at at time zone 'Africa/Cairo')::date between p_from and p_to order by a.created_at desc,a.invoice_id desc limit 200 offset p_offset)t),
 'doctor_payouts',(select coalesce(jsonb_agg(x),'[]') from(select to_jsonb(p) x from clinic_finance.doctor_payouts p where (reviewer or p.created_by=me) and (p.status='pending' or (p.created_at at time zone 'Africa/Cairo')::date between p_from and p_to) order by p.created_at desc,p.id desc limit 200 offset p_offset)t));end $$;
revoke all on all functions in schema clinic_finance from public,anon,authenticated;
do $$declare f record;begin for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'clinic_finance_%' loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to authenticated',f.sig);end loop;end $$;
commit;
